#include "../driver/ucode_upload.h"
#include <assert.h>
#include <stdio.h>
#include <string.h>

static uint8_t primary[64928], extended[37584];

/* Independent trace oracle for the recovered core-130, fresh-chunk path.
 * No expected events are generated by calling production upload code.
 */
struct fake_bus {
    size_t event, fail_at, bank_words[2];
    struct axd_ucode_upload *cancel_job;
    size_t cancel_at;
};

static uint32_t pattern(unsigned int bank, size_t index)
{
    return ((uint32_t)index * 0x1020305u) ^ (bank ? 0x87654321u : 0x12345678u);
}

static int event(struct fake_bus *bus, int kind, uint16_t reg, uint32_t value)
{
    const size_t first_events = 4 + 2 * (sizeof(primary) / 4);
    unsigned int bank = bus->event >= first_events;
    size_t pos = bank ? bus->event - first_events : bus->event;
    assert(bus->event < first_events + 4 + 2 * (sizeof(extended) / 4));
    if (pos == 0) {
        assert(kind == 1 && value == 1); /* store barrier */
    } else if (pos == 1) {
        assert(kind == 2 && reg == 0x160);
        assert(value == (bank ? 0x03080000u : 0x03000000u));
    } else if (pos == 2) {
        assert(kind == 3 && reg == 0x160); /* posted selector readback */
    } else if (pos == 3) {
        assert(kind == 1 && value == 2); /* full barrier */
    } else if (pos % 2 == 0) {
        assert(kind == 1 && value == 1);
    } else {
        assert(kind == 2 && reg == 0x164);
        assert(value == pattern(bank, (pos - 5) / 2));
        bus->bank_words[bank]++;
    }
    /* An error may occur after a simulated side effect. */
    {
        size_t current = bus->event++;
        if (bus->cancel_job != NULL && current == bus->cancel_at)
            axd_upload_cancel(bus->cancel_job);
        return current == bus->fail_at ? -1 : 0;
    }
}

static int write32(void *ctx, uint16_t reg, uint32_t value)
{
    return event(ctx, 2, reg, value);
}

static int read32(void *ctx, uint16_t reg, uint32_t *value)
{
    *value = 0xdeadbeefu; /* Stock writer does not compare this to selector. */
    return event(ctx, 3, reg, 0);
}

static int barrier(void *ctx, enum axd_barrier_kind kind)
{
    return event(ctx, 1, 0, (uint32_t)kind);
}

static void begin(struct axd_ucode_upload *upload)
{
    assert(axd_upload_begin(upload, 130, 1, 0, 0,
                            primary, sizeof(primary), extended, sizeof(extended)) == 0);
}

static void terminal(struct axd_ucode_upload *upload, struct fake_bus *bus,
                       enum axd_upload_phase expected)
{
    size_t before = bus->event;
    assert(axd_upload_step(upload, NULL) == expected);
    assert(axd_upload_cancel(upload) == expected);
    assert(bus->event == before);
}

static void run_bounded(struct axd_ucode_upload *upload,
                          const struct axd_upload_io *io, size_t steps)
{
    size_t i;
    for (i = 0; i < steps; i++) {
        enum axd_upload_phase phase = axd_upload_step(upload, io);
        if (phase == AXD_UPLOAD_TRANSFERRED || phase == AXD_UPLOAD_FAILED ||
            phase == AXD_UPLOAD_CANCELLED)
            return;
    }
}

int main(void)
{
    struct axd_ucode_upload upload;
    struct fake_bus bus = {0, (size_t)-1, {0, 0}, NULL, 0};
    struct axd_upload_io io = {&bus, write32, read32, barrier};
    const size_t first_events = 4 + 2 * (sizeof(primary) / 4);
    const size_t events = first_events + 4 + 2 * (sizeof(extended) / 4);
    const size_t failures[] = {0, 1, 2, 3, 4, 5, 104,
        first_events - 1, first_events, first_events + 1, first_events + 2,
        first_events + 3, first_events + 4, first_events + 5, events - 1};
    const size_t callback_cancellations[] = {0, 1, 2, 3, 4, 5, events - 1};
    unsigned int bank;
    size_t i;
    for (bank = 0; bank < 2; bank++) {
        uint8_t *data = bank ? extended : primary;
        size_t length = bank ? sizeof(extended) : sizeof(primary);
        for (i = 0; i < length / 4; i++) {
            uint32_t value = pattern(bank, i);
            data[4 * i] = (uint8_t)value;
            data[4 * i + 1] = (uint8_t)(value >> 8);
            data[4 * i + 2] = (uint8_t)(value >> 16);
            data[4 * i + 3] = (uint8_t)(value >> 24);
        }
    }
    begin(&upload);
    run_bounded(&upload, &io, events + 1);
    assert(upload.phase == AXD_UPLOAD_TRANSFERRED);
    assert(bus.event == events && upload.attempted_ops == events && upload.completed_ops == events);
    assert(upload.words[0] == sizeof(primary) / 4 && upload.words[1] == sizeof(extended) / 4);
    assert(bus.bank_words[0] == upload.words[0] && bus.bank_words[1] == upload.words[1]);
    terminal(&upload, &bus, AXD_UPLOAD_TRANSFERRED);

    for (i = 0; i < sizeof(failures) / sizeof(failures[0]); i++) {
        memset(&bus, 0, sizeof(bus));
        bus.fail_at = failures[i];
        begin(&upload);
        run_bounded(&upload, &io, events + 1);
        assert(upload.phase == AXD_UPLOAD_FAILED);
        assert(upload.error == AXD_UPLOAD_CALLBACK_ERROR);
        assert(upload.attempted_ops == failures[i] + 1 && upload.completed_ops == failures[i]);
        terminal(&upload, &bus, AXD_UPLOAD_FAILED);
    }
    for (i = 0; i < 3; i++) {
        size_t cancel_at = i == 0 ? 0 : (i == 1 ? 6 : first_events + 3);
        memset(&bus, 0, sizeof(bus));
        bus.fail_at = (size_t)-1;
        begin(&upload);
        run_bounded(&upload, &io, cancel_at);
        assert(bus.event == cancel_at);
        assert(axd_upload_cancel(&upload) == AXD_UPLOAD_CANCELLED);
        terminal(&upload, &bus, AXD_UPLOAD_CANCELLED);
    }
    for (i = 0; i < sizeof(callback_cancellations) / sizeof(callback_cancellations[0]); i++) {
        memset(&bus, 0, sizeof(bus));
        bus.fail_at = (size_t)-1;
        bus.cancel_job = &upload;
        bus.cancel_at = callback_cancellations[i];
        begin(&upload);
        run_bounded(&upload, &io, events + 1);
        assert(upload.phase == AXD_UPLOAD_CANCELLED);
        assert(upload.completed_ops == bus.cancel_at + 1);
        assert(upload.attempted_ops == upload.completed_ops);
        if (bus.cancel_at == 5)
            assert(upload.words[0] == 1);
        if (bus.cancel_at == events - 1)
            assert(upload.words[1] == sizeof(extended) / 4);
        terminal(&upload, &bus, AXD_UPLOAD_CANCELLED);
    }
    memset(&bus, 0, sizeof(bus));
    bus.cancel_job = &upload;
    begin(&upload);
    assert(axd_upload_step(&upload, &io) == AXD_UPLOAD_FAILED);
    assert(upload.error == AXD_UPLOAD_CALLBACK_ERROR && upload.completed_ops == 0);
    terminal(&upload, &bus, AXD_UPLOAD_FAILED);

    /* All validation failures are terminal before any backend operation. */
    assert(axd_upload_begin(&upload, 130, 1, 0, 0, primary, sizeof(primary),
                            extended, sizeof(extended) - 1) != 0);
    assert(upload.attempted_ops == 0 && axd_upload_step(&upload, &io) == AXD_UPLOAD_FAILED);
    assert(axd_upload_begin(&upload, 130, 1, 0, 0, NULL, sizeof(primary),
                            extended, sizeof(extended)) != 0);
    assert(axd_upload_begin(&upload, 130, 2, 0, 0, primary, sizeof(primary),
                            extended, sizeof(extended)) != 0);
    assert(axd_upload_begin(&upload, 129, 1, 0, 0, primary, sizeof(primary),
                            extended, sizeof(extended)) != 0);
    assert(axd_upload_begin(&upload, 130, 1, 0, 1, primary, sizeof(primary),
                            extended, sizeof(extended)) != 0);
    begin(&upload);
    io.read32 = NULL;
    assert(axd_upload_step(&upload, &io) == AXD_UPLOAD_FAILED && upload.attempted_ops == 0);
    puts("upload trace, bank ordering, 15 injected failure points, cancellation and validation passed");
    return 0;
}
